import{_ as a,c as o,o as i,ae as t,j as r}from"./chunks/framework.tuuL-SzM.js";const n="/reel-it-in/main-game-start.png",m=JSON.parse('{"title":"Reel it in!","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"projects/reel-it-in.md","filePath":"projects/reel-it-in.md","lastUpdated":1758920988000}'),l={name:"projects/reel-it-in.md"};function s(h,e,d,c,g,p){return i(),o("div",null,e[0]||(e[0]=[t('<h1 id="reel-it-in" tabindex="-1">Reel it in! <a class="header-anchor" href="#reel-it-in" aria-label="Permalink to &quot;Reel it in!&quot;">​</a></h1><h2 id="play-now" tabindex="-1"><a href="https://gelearthur.itch.io/reelitin" target="_blank" rel="noreferrer"><strong>Play now</strong></a> <a class="header-anchor" href="#play-now" aria-label="Permalink to &quot;[**Play now**](https://gelearthur.itch.io/reelitin)&quot;">​</a></h2>',2),r("iframe",{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/xz8vwJNW9XA",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""},null,-1),t('<p>Reel It In is a chaotic 1v3 couch multiplayer game where players use a fishing rod to pull, push, and sabotage each other!</p><p><img src="'+n+'" alt="GameScreen"></p><h1 id="game-design" tabindex="-1">Game design <a class="header-anchor" href="#game-design" aria-label="Permalink to &quot;Game design&quot;">​</a></h1><p>Our restritions for this game was that it needed to be a couch co-op game. The inspertion came from the niche minecraft mechanic where you can fish hook other players and pull them towards you.</p><p>The goal for our game was to avoid a cannon that is controlled by one of the players. We struggled with is to make it clear to the players that once a penguin has been hit that you swap locations. The cannon goes to the field and the field player goes to the cannon.</p><h2 id="play-testing-is-key" tabindex="-1">Play testing is key <a class="header-anchor" href="#play-testing-is-key" aria-label="Permalink to &quot;Play testing is key&quot;">​</a></h2><p>One big lesson I learned is <strong>PLAY TEST</strong>, <strong>PLAY TEST</strong> and <strong>PLAY TEST</strong>. In the second week we already had a game working. In hindsight we should have done a play test. If you are working on a project your mind gets fixated on one thing. Without extern feedback and you will never know if you made something fun.</p><p>We worked on the game for 7 weeks the project was pretty far in already and it still didn&#39;t feel right. The reeling didn&#39;t feel right the goal was not clear. My solution was to do a playtest. And immediately after I found multiple issues with game design I wrote down all the problems so I could discuses it with the team. I told the team that we need to do a big change. Which is never fun as you are throwing work away. Check out the <a href="https://gelearthur.itch.io/reelitin/devlog/934265/devlog-7-quite-the-turn" target="_blank" rel="noreferrer">dev log week 7</a>. But luckily the game start to become fun.</p><ul><li>Talk about the game design</li><li>How we pivited the other way</li><li>What I will do differently next time</li><li>Unity and perforce</li></ul>',9)]))}const w=a(l,[["render",s]]);export{m as __pageData,w as default};
